	for(ll i = lg; i--;){
		if(d[v] < (1 << i) || d[u] < (1 << i)) continue;
		if(h[v][i] == h[u][i]){
			v = par[v][i];
			u = par[u][i];
		}
	}
	if(d[v] == 0) return 1;
	return (h[v][0] < h[u][0]);
}

